/**
 * The invoice's approval at the tax rate as of today, judged on its {@link #approvalTotal}: a credit note, or an invoice whose grand total
 * (before any withholding) is not over the approval limit and whose discount takes off no more than a
 * fifth of the subtotal, needs none; otherwise it is approved while its grand total is exactly the total
 * it was approved at and no more than {@link #approvalDays} days have passed since it was approved.
 * Once sent, an invoice is as it was approved. Every draft of a client with a HIGH payment risk (highRisk)
 * needs approval, whatever its size, as does every draft that would take its client over its credit limit
 * (overCreditLimit). A draft whose grand total is more than one and a half times the approval limit, or
 * of a HIGH payment risk client, needs {@link #approvalsRequired two approvals} of that same total. So does
 * a draft that is a possible duplicate of an invoice recently sent to its client (possibleDuplicate).
 */
public Approval approval(BigDecimal taxRate, LocalDate today, boolean highRisk, boolean overCreditLimit,
        boolean possibleDuplicate) {
    if (isCreditNote()) {
        return Approval.NOT_NEEDED;
    }
    if (!isDraft()) {
        return approvedTotal == null ? Approval.NOT_NEEDED : Approval.APPROVED;
    }
    BigDecimal limit = approvalLimit();
    BigDecimal total = approvalTotal(taxRate);
    if (!highRisk && !overCreditLimit && !possibleDuplicate && !discountIsLarge() && (limit == null || total.compareTo(limit) <= 0)) {
        return Approval.NOT_NEEDED;
    }
    return approvalsAt(total, today) < approvalsRequired(taxRate) ? Approval.NEEDS_APPROVAL : Approval.APPROVED;
}

/**
 * The approvals a draft needs: two when its client is a HIGH payment risk or its grand total is more than
 * one and a half times the approval limit, else one.
 */
public int approvalsRequired(BigDecimal taxRate) {
    if (highRiskClient) {
        return 2;
    }
    BigDecimal limit = approvalLimit();
    return limit != null && approvalTotal(taxRate).compareTo(limit.multiply(new BigDecimal("1.5"))) > 0 ? 2 : 1;
}

/**
 * The approvals that still stand for the grand total as of today: those given at exactly that total,
 * unless more than {@link #approvalDays} days have passed since the last of them; else none.
 */
private int approvalsAt(BigDecimal total, LocalDate today) {
    if (approvedTotal == null || total.compareTo(approvedTotal) != 0) {
        return 0;
    }
    boolean lapsed = approvedOn != null && today.isAfter(approvedOn.plusDays(approvalDays()));
    return lapsed ? 0 : approvals;
}

